/* ---------------- LMS-parity additions ---------------- */

function extend(table: string, fields: FieldDef[]) {
  const e = ENTITIES.find((x) => x.table === table);
  if (!e) throw new Error(`extend: ${table}`);
  e.fields.push(...fields);
}

